<?php
require_once __DIR__.'/_init.php';require_role(['admin','editor']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$op=$_POST['op']??'';if($op==='approve')$pdo->prepare("UPDATE comments SET status='approved' WHERE id=?")->execute([$id]);if($op==='reject')$pdo->prepare("UPDATE comments SET status='rejected' WHERE id=?")->execute([$id]);if($op==='delete')$pdo->prepare('DELETE FROM comments WHERE id=?')->execute([$id]);redirect('admin/comments.php');}
$adminTitle='Comments';require __DIR__.'/header.php';$comments=$pdo->query('SELECT cm.*,a.title article_title FROM comments cm JOIN articles a ON a.id=cm.article_id ORDER BY cm.created_at DESC')->fetchAll();
?>
<div class="admin-panel"><h2>Comment moderation</h2><div class="table-wrap"><table><thead><tr><th>Comment</th><th>Article</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($comments as $c): ?><tr><td><b><?= e($c['name']) ?></b><br><?= e($c['email']) ?><p><?= nl2br(e($c['comment'])) ?></p></td><td><?= e($c['article_title']) ?></td><td><?= e($c['status']) ?></td><td class="actions"><?php foreach(['approve'=>'Approve','reject'=>'Reject','delete'=>'Delete'] as $op=>$label): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><input type="hidden" name="op" value="<?= $op ?>"><button class="<?= $op==='delete'?'link-danger':'link-button' ?>"><?= $label ?></button></form><?php endforeach; ?></td></tr><?php endforeach; ?><?php if(!$comments): ?><tr><td colspan="4">No comments submitted yet.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__.'/footer.php'; ?>
